    public string? ByteOrder { get; set; }

    /// <summary><c>read_block</c>: Indica qual bloco do cartão MIFARE será automaticamente lido quando aproximado do leitor. Quando vazio, nenhum bloco será lido. O padrão é vazio.</summary>
