{
    /// <summary>Cria a seção.</summary>
    public Rs485Settings()
        : base("rs485")
    {
    }

    /// <summary><c>enabled</c>: Habilita ou desabilita a transmissão de sinal via protocolo RS485. Os valores de entrada possíveis são: "0" (desabilitado) ou "1" (habilitado). Por padrão, o valor de entrada é "0", ou seja, a comunicação padrão não ocorrerá via RS485 e será somente via módulo de acionamento externo (MAE/Security Box)</summary>
    [JsonPropertyName("enabled")]
    public int? Enabled { get; set; }

    /// <summary><c>legacy_mode</c>: Define o modo de comunicação da interface RS485. Os valores de entrada possíveis são: "0", "1" ou "2". Para a entrada "0", a comunicação se comportará de acordo com o manual de comunicação serial RS485 disponível em Manual de Comunicação Serial RS485. Para a entrada "1", ocorrerá o envio do ID, nome e matrícula do usuário autorizado no seguinte formato em hexadecimal: "01 02 &lt; ID até 4 char &gt; 00 00 &lt; nome até 16 char &gt; 00 00 &lt; Matrícula até 6 char &gt; 03 0D". Por fim, se for inserida a entrada "2", a transmissão será do ID do usuário em formato ASCII com 20 dígitos, sem quebra de linha. Por padrão, o valor de entrada de fábrica é "0". *Este parâmetro só está disponível para os equipamentos: iDFlex, iDAccess Pro, iDAccess Nano e iDFace.</summary>
    [JsonPropertyName("legacy_mode")]
    public int? LegacyMode { get; set; }

    /// <summary><c>receive_timeout</c>: Timeout das transmissões de dados (em milissegundos). O valor padrão deste parâmetro é 1000 ms.</summary>
    [JsonPropertyName("receive_timeout")]
    public int? ReceiveTimeout { get; set; }
}

