    /// <summary><c>identification_bits</c>: Indica quantos bits serão usados na identificação da tag UHF, este valor varia dependendo do modo de operação: "Standard" e "Extended". Se for selecionado o modo "Standard" a valor será igual ao valor da saída Wiegand em bits, podendo ser 26, 32, 34 ou 66 bit. Se for selecionado o modo "Extended", será utilizado 96 bits. Valor padrão: 26 bits no modo "Standard"</summary>
    [JsonPropertyName("identification_bits")]
    public int? IdentificationBits { get; set; }

    /// <summary><c>operation_mode</c>: Define o modo de operação, "continuous" para modo contínuo, "trigger" para modo trigger e "inhibit" para modo inibição. No modo contínuo, o dispositivo realizará a leitura de tags independentemente do estado do pino de trigger. No modo trigger, o dispositivo realizará a leitura durante o período de timeout sempre que houver uma borda de descida (pulso) no pino de trigger. Já no modo inibição, o dispositivo não realizará a leitura enquanto o pino de trigger estiver ativado. Quando o pino for desativado, após o período de timeout, o dispositivo voltará a realizar a leitura das tags. Valor padrão: "continuous".</summary>
    [JsonPropertyName("operation_mode")]
    public string? OperationMode { get; set; }

    /// <summary><c>read_interval</c>: Define o intervalo mínimo, em milissegundos, para que duas leituras consecutivas da MESMA tag sejam consideradas leituras distintas, evitando leitura duplicada acidental. Valor mínimo: 100. Valor máximo: 30000. Valor padrão: 5000.</summary>
    [JsonPropertyName("read_interval")]
    public int? ReadInterval { get; set; }

    /// <summary><c>read_interval_diff_tags</c>: Define o intervalo mínimo, em milissegundos, para que duas leituras consecutivas de tags DIFERENTES sejam consideradas leituras distintas, evitando leitura duplicada acidental. Valor mínimo: 250. Valor máximo: 30000. Valor padrão: 100.</summary>
    [JsonPropertyName("read_interval_diff_tags")]
    public int? ReadIntervalDiffTags { get; set; }

    /// <summary><c>reader_type</c>: Define a ordem dos bytes, podendo ter os seguintes valores: "lsb" ou "default". Valor padrão: "default".</summary>
    [JsonPropertyName("reader_type")]
    public string? ReaderType { get; set; }

    /// <summary><c>tag_detector_enabled</c>: Indica o modo de funcionamento do relé interno da iDUHF. Caso seja "0", o dispositivo assume o comportamento padrão em relação à abertura do relé interno. Caso seja "1", sempre que uma tag estiver visível, o relé estará ativo. Logo, enquanto uma ou mais tags estiverem na frente da antena, o relé ficará ativo. Se estiver habilitada, o relé interno da iDUHF fica reservado a essa funcionalidade. Valor padrão: 0.</summary>
    [JsonPropertyName("tag_detector_enabled")]
    public int? TagDetectorEnabled { get; set; }

    /// <summary><c>transmit_power</c>: Define a potência de transmissão da antena. Este valor é dividido por 100 para obter o valor em dBm. Valor mínimo: 1500. Valor máximo: 2400. Valor padrão: 2400.</summary>
    [JsonPropertyName("transmit_power")]
    public int? TransmitPower { get; set; }

    /// <summary><c>trig_idle</c>: Indica qual o nível lógico do trigger quando ele estiver ocioso. Valores: "0" ou "1". Valor padrão: 1.</summary>
    [JsonPropertyName("trig_idle")]
    public int? TrigIdle { get; set; }

    /// <summary><c>trigger_timeout</c>: Define o timeout do trigger, em milissegundos. Usado somente quando operation_mode for configurado para modo trigger. Valor mínimo: 250. Valor máximo: 60000. Valor padrão: desativado.</summary>
    [JsonPropertyName("trigger_timeout")]
    public int? TriggerTimeout { get; set; }

    /// <summary><c>work_channel</c>: Define os canais de operação da antena que serão usados. Exemplo: permitir canais 1, 2, 3, 4, 5, 7, 8, 9 e 10: "1-5;7-10"</summary>
    [JsonPropertyName("work_channel")]
    public string? WorkChannel { get; set; }
}

